diff --git a/repro/emfile-fix.js b/repro/emfile-fix.js
new file mode 100644
index 0000000..7514427
--- /dev/null
+++ b/repro/emfile-fix.js
@@ -0,0 +1,76 @@
+#!/usr/bin/env node
+/**
+ * Check for "running `--fix` throws EMFILE: too many open files".
+ *
+ * Creates FILES (default 600) files that each have auto-fixable problems, runs
+ * `eslint . --fix` on them with the open-file limit (`ulimit -n`) lowered to
+ * FD_LIMIT (default 256), and asserts the expected behavior from the report:
+ * all files are fixed and ESLint exits 0 without an error.
+ *
+ * Exit code: 0 when `--fix` fixes every file, 1 otherwise.
+ *
+ * Usage (from the repo root):  node repro/emfile-fix.js
+ * Optional env: FILES, FD_LIMIT (e.g. FD_LIMIT=20000 to see it pass).
+ */
+"use strict";
+
+const fs = require("node:fs");
+const os = require("node:os");
+const path = require("node:path");
+const { spawnSync } = require("node:child_process");
+
+const FILES = Number(process.env.FILES || 600);
+const FD_LIMIT = Number(process.env.FD_LIMIT || 256);
+const repoRoot = path.resolve(__dirname, "..");
+const eslintBin = path.join(repoRoot, "bin", "eslint.js");
+
+const dir = fs.mkdtempSync(path.join(os.tmpdir(), "eslint-emfile-"));
+const source = "var a = 1;\nvar b = 2;\nconsole.log(a, b);\n";
+
+fs.writeFileSync(
+	path.join(dir, "eslint.config.js"),
+	'module.exports = [{ rules: { "no-var": "error", "prefer-const": "error" } }];\n',
+);
+for (let i = 0; i < FILES; i++) {
+	fs.writeFileSync(path.join(dir, `file${i}.js`), source);
+}
+
+// Same command as the report (`eslint ./ --fix`), run with a lowered fd limit.
+const result = spawnSync(
+	"sh",
+	["-c", `ulimit -n ${FD_LIMIT} && exec "$0" "$@"`, process.execPath, eslintBin, "./", "--fix"],
+	{ cwd: dir, encoding: "utf8", maxBuffer: 1 << 28 },
+);
+
+const stillBroken = [];
+for (let i = 0; i < FILES; i++) {
+	if (fs.readFileSync(path.join(dir, `file${i}.js`), "utf8").includes("var ")) {
+		stillBroken.push(i);
+	}
+}
+fs.rmSync(dir, { recursive: true, force: true });
+
+const output = `${result.stdout || ""}${result.stderr || ""}`;
+const failures = [];
+
+if (result.error) {
+	failures.push(`could not run eslint: ${result.error.message}`);
+}
+if (/EMFILE/.test(output)) {
+	failures.push(`ESLint threw: ${output.split("\n").find(l => /EMFILE/.test(l)).trim()}`);
+}
+if (result.status !== 0) {
+	failures.push(`eslint exited with ${result.status}, expected 0`);
+}
+if (stillBroken.length > 0) {
+	failures.push(`${stillBroken.length}/${FILES} files were not fixed`);
+}
+
+if (failures.length > 0) {
+	console.error(`FAIL (FILES=${FILES}, ulimit -n ${FD_LIMIT}):`);
+	for (const f of failures) {
+		console.error(`  - ${f}`);
+	}
+	process.exit(1);
+}
+console.log(`PASS: all ${FILES} files fixed (ulimit -n ${FD_LIMIT})`);
